cd /app && python - <<'EOF'
p='statements/meridale.py'
s=open(p).read()
a=s.index("def _amount")
new='''_LINKS = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}
_SUPPORTED = ("en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP")
_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
# locale -> (decimal, group, code before?)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True),
    "en-IN": (".", ",", True), "pt-BR": (",", ".", True),
    "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if m.group(3) and int(m.group(3)) != 0:
            raise ValueError(f"unsupported fixed offset {tz}")
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'-' if m.group(1) == '+' else '+'}{hours}"
    return _LINKS.get(tz, tz)


def _locale(loc: str) -> str:
    loc = re.split(r"[.@]", loc.strip())[0].replace("_", "-")
    parts = loc.split("-")
    lang = parts[0].lower()
    tag = lang + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    for sup in _SUPPORTED:
        if sup.lower() == tag.lower():
            return sup
    return lang if lang in _SUPPORTED else "en-US"


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _round(value: str, currency: str) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-_digits(currency)), rounding=ROUND_HALF_EVEN)


def _group(intpart: str, locale: str, sep: str) -> str:
    if locale == "es" and len(intpart) == 4:
        return intpart
    if locale == "en-IN":
        if len(intpart) <= 3:
            return intpart
        head, tail = intpart[:-3], intpart[-3:]
        chunks = []
        while len(head) > 2:
            chunks.insert(0, head[-2:])
            head = head[:-2]
        if head:
            chunks.insert(0, head)
        return sep.join(chunks + [tail])
    chunks = []
    while len(intpart) > 3:
        chunks.insert(0, intpart[-3:])
        intpart = intpart[:-3]
    return sep.join([intpart] + chunks)


def _text(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, before = _STYLE[locale]
    d = _digits(currency)
    neg = value < 0
    digits = f"{abs(value):.{d}f}"
    intpart, _, frac = digits.partition(".")
    num = _group(intpart, locale, grp) + (dec + frac if d else "")
    if neg:
        num = "-" + num
    return f"{currency}\\u00a0{num}" if before else f"{num}\\u00a0{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    end = date(year + month // 12, month % 12 + 1, 1)  # half-open: the day after the last
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": end.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    cur = report["currency"]
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_round(d[k], cur) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _text(net, cur, locale)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-_digits(cur)))
    return Statement(merchant.id, cur, tuple(lines), total, _text(total, cur, locale))
'''
s=s[:a]+new
s=s.replace("import json\n","import json\nimport re\n").replace("from decimal import Decimal","from decimal import ROUND_HALF_EVEN, Decimal")
open(p,'w').write(s)
